    static let background = Color("onbBackground")
    static let inkPrimary = Color("inkPrimary")
    static let inkSecondary = Color("inkSecondary")
    static let inkTertiary = Color("inkTertiary")
    /// Filled dots, badge, ripple and slot outline.
    static let accent = Color("onbAccent")
    /// Skip and the back chevron.
    static let accentText = Color("accentText")
    static let ctaFill = Color("ctaFill")
    static let ctaLabel = Color("ctaLabel")
    static let ctaShadow = Color("ctaShadow")
    static let stampWordFill = Color("stampWordFill")
