    static let postmark = Color("postmark")
    static let passportPaper = Color("passportPaper")
    static let passportHairline = Color("passportHairline")
    static let passportShadow = Color("passportShadow")
    static let passportSpine = Color("passportSpine")
    static let passportRings = Color("passportRings")
    static let passportDash = Color("passportDash")
    static let passportHeader = Color("passportHeader")
    static let screenGlow = Color("screenGlow")
    static let shadowSoft = Color("shadowSoft")
    static let shadowDeep = Color("shadowDeep")
    static let ctaDisabledFill = Color("ctaDisabledFill")
    static let ctaDisabledLabel = Color("ctaDisabledLabel")
    static let slotFill = Color("slotFill")
